oxy_webhelp_navlinks = {"ms_copilot_studio_agent_operations-d39536e62110":{"topics":[{"title":"Microsoft Copilot Studio requirements and limitations for <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\">Deploying <span class=\"ph\">Agent Cloud<\/span> with Microsoft Copilot Studio requires specific         components, administrator roles, API access, and table permissions. The requirements differ         for a custom app registration, which Rubrik recommends, and the Rubrik-managed application.         A Copilot Studio limitation causes <span class=\"ph\">Agent Cloud<\/span> to display conversations only         after 30 minutes of inactivity.<\/p>","href":"agent_cloud\/ms_copilot_studio_requirements_limitations_agent_cloud.html","attributes":{"data-id":"ms_copilot_studio_requirements_limitations_agent_cloud"},"menu":{"hasChildren":false},"tocID":"ms_copilot_studio_requirements_limitations_agent_cloud-d39536e62125","topics":[]},{"title":"Deploying Microsoft Copilot Studio for custom app registration","shortdesc":"<p class=\"shortdesc\">Connect up to 500 Microsoft Copilot Studio environments to <span class=\"ph\">Agent Cloud<\/span> in         a single connection using an app registration that you create and manage.<\/p>","href":"agent_cloud\/deploying_mscs_custom_app_registration.html","attributes":{"data-id":"deploying_mscs_custom_app_registration"},"menu":{"hasChildren":false},"tocID":"deploying_mscs_custom_app_registration-d39536e62144","next":"deploying_mscs_custom_app_registration-d39536e62144"},{"title":"Deploying Microsoft Copilot Studio for Rubrik-managed applications","shortdesc":"<p class=\"shortdesc\">Connect a single Microsoft Copilot Studio environment to <span class=\"ph\">Agent Cloud<\/span> by         using an application that Rubrik creates and manages in your Microsoft Entra tenant, to         enable agent discovery, activity logging, and real-time tool blocking.<\/p>","href":"agent_cloud\/deploying_mscs_rubrik_managed_apps.html","attributes":{"data-id":"deploying_mscs_rubrik_managed_apps"},"menu":{"hasChildren":false},"tocID":"deploying_mscs_rubrik_managed_apps-d39536e62172","next":"deploying_mscs_rubrik_managed_apps-d39536e62172"},{"title":"Enabling tool blocking on existing Rubrik-managed connections","shortdesc":"<p class=\"shortdesc\">Enable tool blocking on an existing connection that uses the Rubrik-managed         application so that Microsoft Copilot Studio intercepts and blocks unauthorized tool usage         and policy violations in real time using <span class=\"ph\">Agent Cloud<\/span>.<\/p>","href":"agent_cloud\/enabling_tool_blocking_existing_copilot_connections.html","attributes":{"data-id":"enabling_tool_blocking_existing_copilot_connections"},"menu":{"hasChildren":false},"tocID":"enabling_tool_blocking_existing_copilot_connections-d39536e62200","topics":[]},{"title":"Troubleshooting discovery errors","shortdesc":"<p class=\"shortdesc\">Information about resolving errors that <span class=\"ph\">Agent Cloud<\/span> displays when it         discovers or connects Microsoft Copilot Studio environments with a custom app         registration.<\/p>","href":"agent_cloud\/troubleshooting_discovery_errors.html","attributes":{"data-id":"troubleshooting_discovery_errors"},"menu":{"hasChildren":false},"tocID":"troubleshooting_discovery_errors-d39536e62214","topics":[]}]}};